// ── API Gateway routing logic (Node.js / Express) ─────────────
// A gateway handles cross-cutting concerns ONCE so services don't each implement them

const routes = {
  '/auth':     'http://auth-service:3001',
  '/orders':   'http://order-service:3002',
  '/products': 'http://product-service:3003',
};

// In-memory rate limiter (production: use Redis)
const requestCounts = new Map();
function isRateLimited(ip) {
  const count = (requestCounts.get(ip) || 0) + 1;
  requestCounts.set(ip, count);
  return count > 100; // 100 requests per window
}

async function gatewayHandler(req, res) {
  // 1. Auth check — centralised; services trust the injected header
  const token = req.headers['authorization'];
  if (!token) return res.status(401).json({ error: 'Unauthorized' });

  let userId;
  try {
    userId = verifyJWT(token); // throws if invalid
  } catch {
    return res.status(401).json({ error: 'Invalid token' });
  }

  // 2. Rate limiting — also a gateway concern
  if (isRateLimited(req.ip)) {
    return res.status(429).json({ error: 'Too Many Requests' });
  }

  // 3. Route to the correct upstream service
  const match = Object.entries(routes)
    .find(([prefix]) => req.path.startsWith(prefix));
  if (!match) return res.status(404).json({ error: 'Not Found' });

  const [, upstream] = match;

  // 4. Forward the request; inject identity as a trusted internal header
  const response = await fetch(upstream + req.path, {
    method: req.method,
    headers: {
      'Content-Type': 'application/json',
      'x-user-id': userId,      // services trust this; they don't re-verify the JWT
      'x-request-id': req.headers['x-request-id'] || crypto.randomUUID(),
    },
    body: req.method !== 'GET' ? JSON.stringify(req.body) : undefined,
  });

  const data = await response.json();
  res.status(response.status).json(data);
}

// ── Message queue producer + idempotent consumer pattern ───────

// PRODUCER: Order Service publishes after saving to DB
async function createOrder(userId, items) {
  // 1. Save to DB first — the source of truth
  const order = await db.orders.create({ userId, items, status: 'pending' });

  // 2. Publish event — fire and forget; consumer handles async work
  await queue.publish('order.created', {
    orderId: order.id,
    userId,
    items,
    createdAt: order.createdAt,
  });

  return order; // return immediately; don't wait for downstream consumers
}

// CONSUMER: Notification Service — must be idempotent
async function handleOrderCreated(event) {
  const { orderId, userId } = event;

  // Idempotency check: skip if we already processed this event
  const alreadyProcessed = await db.processedEvents.findOne({ orderId });
  if (alreadyProcessed) {
    console.log(`Skipping duplicate event for order ${orderId}`);
    return; // safe to ack — we already did the work
  }

  // Do the actual work
  const user = await userService.getUser(userId);
  await emailService.sendOrderConfirmation(user.email, orderId);

  // Record that we processed this event (prevents duplicate emails)
  await db.processedEvents.create({ orderId, processedAt: new Date() });

  // Ack — broker removes the message
  return 'ack';
}

// CONSUMER REGISTRATION (RabbitMQ-style)
queue.subscribe('order.created', async (message) => {
  try {
    await handleOrderCreated(message.data);
    message.ack();
  } catch (err) {
    console.error('Processing failed, will retry:', err);
    message.nack({ requeue: true }); // broker redelivers after a delay
  }
});

// ── Circuit breaker implementation (simplified) ─────────────────

class CircuitBreaker {
  constructor(fn, { failureThreshold = 5, cooldownMs = 10000 } = {}) {
    this.fn = fn;
    this.failureThreshold = failureThreshold;
    this.cooldownMs = cooldownMs;
    this.state = 'CLOSED'; // CLOSED | OPEN | HALF_OPEN
    this.failureCount = 0;
    this.lastFailureTime = null;
  }

  async call(...args) {
    if (this.state === 'OPEN') {
      const elapsed = Date.now() - this.lastFailureTime;
      if (elapsed < this.cooldownMs) {
        throw new Error('Circuit OPEN — fast failing to protect downstream');
      }
      // Cooldown expired — try a probe
      this.state = 'HALF_OPEN';
    }

    try {
      const result = await this.fn(...args);
      this._onSuccess();
      return result;
    } catch (err) {
      this._onFailure();
      throw err;
    }
  }

  _onSuccess() {
    this.failureCount = 0;
    this.state = 'CLOSED'; // probe succeeded in HALF_OPEN → close
  }

  _onFailure() {
    this.failureCount++;
    this.lastFailureTime = Date.now();
    if (this.failureCount >= this.failureThreshold) {
      this.state = 'OPEN';
      console.warn(`Circuit OPENED after ${this.failureCount} failures`);
    }
  }
}

// Usage: wrap any remote call
const breaker = new CircuitBreaker(
  (orderId) => fetch(`http://payment-service/pay/${orderId}`),
  { failureThreshold: 3, cooldownMs: 5000 }
);

async function processPayment(orderId) {
  try {
    return await breaker.call(orderId);
  } catch (err) {
    if (err.message.includes('Circuit OPEN')) {
      // Return a degraded response rather than propagating the error
      return { status: 'pending', message: 'Payment queued for retry' };
    }
    throw err;
  }
}
